package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.ruoyi.medical.identity.ApplicationSessionIdentity;import jakarta.servlet.http.HttpServletResponse;import org.springframework.web.bind.annotation.*;import org.springframework.beans.factory.ObjectProvider;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.core.Authentication;
@RestController
public final class FormalInvocationAvailabilityController {
 private final ApplicationSessionIdentity identities;private final EnterpriseAccess access;private final ObjectProvider<FormalInvocationService> services;private final int input,result,raw;
 public FormalInvocationAvailabilityController(ApplicationSessionIdentity identities,EnterpriseAccess access,ObjectProvider<FormalInvocationService> services,@Value("${medical.formal-invocation.maximum-input-bytes:0}")int input,@Value("${medical.formal-invocation.maximum-result-bytes:0}")int result,@Value("${medical.formal-invocation.maximum-raw-response-bytes:0}")int raw){this.identities=identities;this.access=access;this.services=services;this.input=input;this.result=result;this.raw=raw;}
 @GetMapping("/api/formal-invocations/availability")public JsonNode read(jakarta.servlet.http.HttpServletRequest request,Authentication authentication,HttpServletResponse response){var identity=identities.requireCurrent(request,authentication);return access.execute(identity,a->{boolean enabled=services.getIfAvailable()!=null;var data=new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode().put("schema_version","1.0.0").put("current_context",a.context().context_revision()).put("formal_invocation_enabled",enabled).put("supported_execution_kind","MODEL_VERIFICATION").put("supported_model_scope","PROJECT_SAME_OWNER").put("supported_provider","deepseek").put("required_reasoning_effort","none").put("provider_reconciliation_supported",false).put("provider_cancel_supported",false).put("unknown_send_can_retry",false).put("receipt_recovery_requires_original_bytes",true);if(enabled){data.put("maximum_input_bytes",input).put("maximum_result_bytes",result).put("maximum_raw_response_bytes",raw).put("maximum_http_body_bytes",16777216);}else{data.putNull("maximum_input_bytes").putNull("maximum_result_bytes").putNull("maximum_raw_response_bytes").putNull("maximum_http_body_bytes");}return org.springframework.util.function.ThrowingSupplier.of(()->FormalInvocationResponses.envelope(data,a.context().context_revision(),response)).get();});}
}
